const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(node=>observer.observe(node));
const copy={mr:['无需配置，开箱即搜','版本过滤 · 依赖追踪 · SHA-1 校验'],cf:['你的 Key，只留在你的电脑','官方接口 · 安全存储 · 依赖追踪']};document.querySelectorAll('.tabs button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.tabs button').forEach(item=>item.classList.toggle('active',item===button));const value=copy[button.dataset.source];document.getElementById('sourceTitle').textContent=value[0];document.getElementById('sourceText').textContent=value[1]}));
const art=document.querySelector('[data-tilt]');if(art&&!matchMedia('(prefers-reduced-motion: reduce)').matches){art.addEventListener('pointermove',event=>{const box=art.getBoundingClientRect(),x=(event.clientX-box.left)/box.width-.5,y=(event.clientY-box.top)/box.height-.5;art.style.transform=`rotateY(${x*3}deg) rotateX(${-y*3}deg)`});art.addEventListener('pointerleave',()=>art.style.transform='')}
const exeParts=['part00','part01','part02','part03','part04'].map(part=>`downloads/Lite-MC-Portable.${part}`);document.querySelector('[data-exe-download]').addEventListener('click',async event=>{event.preventDefault();const button=event.currentTarget,label=document.getElementById('fileSize');if(button.dataset.busy)return;button.dataset.busy='true';try{const chunks=[];let received=0;for(let index=0;index<exeParts.length;index++){label.textContent=`正在准备 ${(index/exeParts.length*100).toFixed(0)}%`;const response=await fetch(exeParts[index]);if(!response.ok)throw new Error(`part ${index}`);const chunk=await response.arrayBuffer();chunks.push(chunk);received+=chunk.byteLength}const blob=new Blob(chunks,{type:'application/vnd.microsoft.portable-executable'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Lite-MC-1.1.0-Portable-x64.exe';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);label.textContent=`${(received/1024/1024).toFixed(1)} MB · 下载完成`}catch(error){label.textContent='下载失败，请重试';button.dataset.busy=''}finally{if(label.textContent.includes('下载完成'))delete button.dataset.busy}});
